     3→import kotlinx.browser.localStorage
     4→import kotlinx.coroutines.flow.Flow
     5→import kotlinx.coroutines.flow.MutableStateFlow
     6→import kotlinx.coroutines.flow.map
     7→import kotlinx.coroutines.flow.update
     8→import kotlinx.serialization.json.Json
     9→
    10→private const val PREFS_KEY = "bookreads_prefs"
    11→
    12→internal class PrefServiceLocalStorage : LocalStorageService {
    13→    private val json = Json { ignoreUnknownKeys = true }
    14→    private val prefsFlow = MutableStateFlow(load())
    15→
    16→    private fun load(): AppPreferences {
    17→        val raw = localStorage.getItem(PREFS_KEY) ?: return AppPreferences()
    18→        return try {
    19→            json.decodeFromString(AppPreferences.serializer(), raw)
    20→        } catch (_: Throwable) {
    21→            AppPreferences()
    22→        }
    23→    }
    24→
    25→    private fun save(prefs: AppPreferences) {
    26→        localStorage.setItem(PREFS_KEY, json.encodeToString(AppPreferences.serializer(), prefs))
    27→    }
    28→
    29→    override fun getUsername(): Flow<String?> = prefsFlow.map { it.username }
    30→
    31→    override suspend fun setUsername(username: String?) {
    32→        prefsFlow.update { it.copy(username = username) }
    33→        save(prefsFlow.value)
    34→    }
    35→
    36→    override fun getActiveSession(): Flow<ActiveSession?> = prefsFlow.map { it.activeSession }
    37→
    38→    override suspend fun saveActiveSession(session: ActiveSession) {
    39→        prefsFlow.update { it.copy(activeSession = session) }
    40→        save(prefsFlow.value)
    41→    }
    42→
    43→    override suspend fun clearActiveSession() {
    44→        prefsFlow.update { it.copy(activeSession = null) }
    45→        save(prefsFlow.value)
    46→    }
    47→}
